@Composable fun ReadingPageProgress(entry:JSONObject){val total=entry.optInt("totalPages");val current=entry.optInt("currentPage");Text(if(total>0)"$current / $total pages · ${current*100/total}%" else "$current pages · total not set");if(total>0)LinearProgressIndicator(progress={current.toFloat()/total},modifier=Modifier.fillMaxWidth())}
@Composable fun ReadingInsights(reader:JSONObject,entries:List<JSONObject>,books:List<JSONObject>,enabled:Boolean,onChange:(String,JSONObject,()->Unit)->Unit){
 var year by remember{mutableStateOf(LocalDate.now().year.toString())};var goal by remember(reader.toString(),year){mutableStateOf(reader.optJSONObject("annualGoals")?.optInt(year)?.toString()?:"0")}
 val sessions=entries.flatMap{e->(e.optJSONArray("sessions")?.objects()?:emptyList())+(if(e.optString("status")=="finished")listOf(e)else emptyList())}
 val finished=sessions.filter{it.optString("finishedDate").startsWith("$year-")};val pages=finished.sumOf{if(it.optInt("totalPages")>0)it.optInt("totalPages") else it.optInt("currentPage")};val target=reader.optJSONObject("annualGoals")?.optInt(year)?:0
 PhonePanel{Text("Reading insights",style=MaterialTheme.typography.titleLarge);OutlinedTextField(year,{year=it.filter(Char::isDigit).take(4)},label={Text("Summary year")});Text("${finished.size} reads completed · $pages pages in completed reads");if(target>0){Text("Annual goal: ${finished.size} / $target");LinearProgressIndicator(progress={(finished.size.toFloat()/target).coerceIn(0f,1f)},modifier=Modifier.fillMaxWidth())};OutlinedTextField(goal,{goal=it.filter(Char::isDigit).take(5)},label={Text("Books goal (0 removes)")});TextButton(enabled=enabled&&year.toIntOrNull() in 1900..2200&&goal.toIntOrNull() in 0..10000,onClick={onChange("setReadingGoal",JSONObject().put("readerId",reader.optString("id")).put("year",year.toInt()).put("books",goal.toInt())){}}){Text("Save goal")};Text("Each reread counts separately. Unknown lengths contribute only recorded pages; undated completions stay in history.");var summaries by remember{mutableStateOf(false)};TextButton(onClick={summaries=!summaries}){Text("Monthly / yearly summaries & optional completion streak")};if(summaries){(1..12).forEach{month->val records=finished.filter{it.optString("finishedDate").drop(5).take(2).toIntOrNull()==month};Text("$month: ${records.size} reads · ${records.sumOf{if(it.optInt("totalPages")>0)it.optInt("totalPages")else it.optInt("currentPage")}} pages")};sessions.filter{it.optString("finishedDate").isNotBlank()}.groupingBy{it.optString("finishedDate").take(4)}.eachCount().toSortedMap().forEach{(y,n)->Text("$y: $n completed reads")};val genreCounts=entries.flatMap{e->val count=(e.optJSONArray("sessions")?.objects()?:emptyList()).count{it.optString("finishedDate").startsWith("$year-")}+(if(e.optString("status")=="finished"&&e.optString("finishedDate").startsWith("$year-"))1 else 0);List(count){books.find{it.optString("id")==e.optString("copyId")}?.optString("genre")?.ifBlank{"Not recorded"}?:"Not recorded"}}.groupingBy{it}.eachCount();genreCounts.forEach{(g,n)->Text("$g: $n")};val days=finished.mapNotNull{runCatching{LocalDate.parse(it.optString("finishedDate"))}.getOrNull()}.distinct().sorted();var run=0;var best=0;var previous:LocalDate?=null;days.forEach{day->run=if(previous?.plusDays(1)==day)run+1 else 1;best=maxOf(best,run);previous=day};Text("Longest completion streak: $best days. Counts finished-book dates, not inferred daily reading.")}}
}
@Composable fun ReadingDetails(entry:JSONObject,readerId:String,enabled:Boolean,error:String,onChange:(String,JSONObject,()->Unit)->Unit,onClose:()->Unit){
 var kind by remember{mutableStateOf("quote")};var text by remember{mutableStateOf("")};var page by remember{mutableStateOf("")};var reread by remember{mutableStateOf(false)};var remove by remember{mutableStateOf("")}
 fun input()=JSONObject().put("readerId",readerId).put("copyId",entry.optString("copyId"))
 Dialog(onDismissRequest=onClose){Surface{Column(Modifier.padding(20.dp).verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("Sessions, quotes & notes",style=MaterialTheme.typography.titleLarge);ReadingPageProgress(entry);if(entry.optString("status")=="finished")Button(enabled=enabled,onClick={reread=true}){Text("Start a reread")};Text("Earlier sessions",style=MaterialTheme.typography.titleMedium);(entry.optJSONArray("sessions")?.objects()?:emptyList()).forEach{s->PhonePanel{Text("${s.optString("startedDate").ifBlank{"No start date"}} → ${s.optString("finishedDate").ifBlank{"No finish date"}}");ReadingPageProgress(s);Text("Rating ${s.optInt("rating")}/5");Text(s.optString("notes"))}};Text("Favorite quotes & page notes",style=MaterialTheme.typography.titleMedium);(entry.optJSONArray("annotations")?.objects()?:emptyList()).forEach{a->PhonePanel{Text(a.optString("kind")+if(!a.isNull("page"))" · Page ${a.optInt("page")}"else "");Text(a.optString("text"));TextButton(enabled=enabled,onClick={remove=a.optString("id")}){Text("Delete")}}};TextButton(onClick={kind=if(kind=="quote")"note"else "quote"}){Text("Type: $kind")};OutlinedTextField(page,{page=it.filter(Char::isDigit).take(6)},label={Text("Page (optional)")});OutlinedTextField(text,{text=it.take(4000)},label={Text("Quote / personal note")},minLines=3);Button(enabled=enabled&&text.isNotBlank()&&(page.isBlank()||page.toIntOrNull() in 1..100000),onClick={onChange("saveReadingAnnotation",input().put("kind",kind).put("text",text).put("page",if(page.isBlank())JSONObject.NULL else page.toInt()),onClose)}){Text("Add quote / note")};if(error.isNotBlank())Text(error,color=MaterialTheme.colorScheme.error);TextButton(onClick=onClose){Text("Close")}}}}
 if(reread)AlertDialog(onDismissRequest={reread=false},title={Text("Start another read?")},text={Text("Preserve the finished session, dates, progress, rating and notes before starting a new one.")},confirmButton={TextButton(enabled=enabled,onClick={onChange("startReread",input(),onClose)}){Text("Start reread")}},dismissButton={TextButton(onClick={reread=false}){Text("Cancel")}})
 if(remove.isNotBlank())AlertDialog(onDismissRequest={remove=""},title={Text("Delete quote / note?")},confirmButton={TextButton(enabled=enabled,onClick={onChange("removeReadingAnnotation",input().put("annotationId",remove),onClose)}){Text("Delete")}},dismissButton={TextButton(onClick={remove=""}){Text("Cancel")}})
}
